  "sub_graphs": [
    {
      "id": "SG-TRIE-DATA-STRUCTURES",
      "name": "Trie Node Data Structures",
      "description": "Defines the core data structures used to represent nodes in the Merkle Patricia Trie: LeafNode, ExtensionNode, BranchNode, and the Trie container itself. All node dataclasses use @slotted_freezable for immutability after construction.",
      "invariants": [
        {
          "id": "INV-TRIE-DS-001",
          "text": "LeafNode, ExtensionNode, and BranchNode are frozen (immutable) after creation via @slotted_freezable decorator."
        },
        {
          "id": "INV-TRIE-DS-002",
          "text": "BranchSubnodes is a fixed-length tuple of exactly 16 Extended elements, corresponding to the 16 possible nibble values (0x0-0xF)."
        },
        {
          "id": "INV-TRIE-DS-003",
          "text": "InternalNode is a union type of exactly LeafNode | ExtensionNode | BranchNode — no other node types are permitted internally."
        },
        {
          "id": "INV-TRIE-DS-004",
          "text": "Node is a union type: Account | Bytes | LegacyTransaction | Receipt | Uint | U256 | Withdrawal | None — representing all values storable in the trie."
        },
        {
          "id": "INV-TRIE-DS-005",
          "text": "The Trie generic container is parameterized by K (key type, bound to Bytes) and V (value type, constrained to specific Optional union types)."
        }
      ],
      "functions": [],
      "state_variables": [
        {
          "id": "SV-TRIE-DS-001",
          "name": "LeafNode.rest_of_key",
          "type": "Bytes",
          "description": "The remaining portion of the key (in nibble form) that uniquely identifies this leaf within its branch path."
        },
        {
          "id": "SV-TRIE-DS-002",
          "name": "LeafNode.value",
          "type": "Extended",
          "description": "The RLP-encoded value stored at this leaf node."
        },
        {
          "id": "SV-TRIE-DS-003",
          "name": "ExtensionNode.key_segment",
          "type": "Bytes",
          "description": "The shared key prefix (in nibble form) that this extension node compresses."
        },
        {
          "id": "SV-TRIE-DS-004",
          "name": "ExtensionNode.subnode",
          "type": "Extended",
          "description": "The encoded child node that follows this extension's key segment."
        },
        {
          "id": "SV-TRIE-DS-005",
          "name": "BranchNode.subnodes",
          "type": "BranchSubnodes (Tuple of 16 Extended)",
          "description": "Fixed-length tuple of 16 child references, one for each possible nibble value (0x0-0xF)."
        },
        {
          "id": "SV-TRIE-DS-006",
          "name": "BranchNode.value",
          "type": "Extended",
          "description": "The value stored at this branch node itself (for keys that terminate exactly at this branch level)."
        },
        {
          "id": "SV-TRIE-DS-007",
          "name": "Trie.secured",
          "type": "bool",
          "description": "If True, keys are keccak256-hashed before insertion, creating a 'secure' trie."
        },
        {
          "id": "SV-TRIE-DS-008",
          "name": "Trie.default",
          "type": "V",
          "description": "The default value returned for missing keys and used to determine deletion (value == default triggers removal)."
        },
        {
          "id": "SV-TRIE-DS-009",
          "name": "Trie._data",
          "type": "Dict[K, V]",
          "description": "Internal dictionary storing the key-value pairs of the trie. Keys are raw (pre-hashing) byte sequences."
        }
      ],
      "data_structures": [
        {
          "id": "DS-TRIE-001",
          "name": "LeafNode",
          "type": "dataclass",
          "fields": ["rest_of_key: Bytes", "value: Extended"],
          "decorators": ["@slotted_freezable", "@dataclass"],
          "description": "Leaf node in the Merkle Trie. Stores the remaining key suffix and the associated value."
        },
        {
          "id": "DS-TRIE-002",
          "name": "ExtensionNode",
          "type": "dataclass",
          "fields": ["key_segment: Bytes", "subnode: Extended"],
          "decorators": ["@slotted_freezable", "@dataclass"],
          "description": "Extension node in the Merkle Trie. Compresses a shared key prefix into a single node pointing to a subnode."
