        {
          "id": "DS-TRIE-003",
          "name": "BranchNode",
          "type": "dataclass",
          "fields": ["subnodes: BranchSubnodes", "value: Extended"],
          "decorators": ["@slotted_freezable", "@dataclass"],
          "description": "Branch node in the Merkle Trie. Contains 16 child slots (one per nibble) plus an optional value."
        },
        {
          "id": "DS-TRIE-004",
          "name": "Trie",
          "type": "dataclass (Generic[K, V])",
          "fields": ["secured: bool", "default: V", "_data: Dict[K, V]"],
          "decorators": ["@dataclass"],
          "description": "The Merkle Trie container. A generic key-value store with optional key hashing (secured mode) and a default value for missing keys."
