    {
      "id": "SG-TRIE-CONSTANTS",
      "name": "Trie Constants and Sentinel Values",
      "description": "Defines key constants for the trie module, most importantly EMPTY_TRIE_ROOT which is the keccak256 hash of the RLP encoding of an empty byte string.",
      "invariants": [
        {
          "id": "INV-CONST-001",
          "text": "EMPTY_TRIE_ROOT == keccak256(RLP(b'')) == 0x56e81f171bcc55a6ff8345e692c0f86e5b48e01b996cadc001622fb5e363b421. This is the canonical root hash for any empty trie (secured or unsecured)."
        },
        {
          "id": "INV-CONST-002",
          "text": "keccak256(RLP(())) == 0x1dcc4de8dec75d7aab85b567b6ccd41ad312451b948a7413f0a142fd40d49347, which is the sha3Uncles hash in block headers with no uncles. (Documented but not a variable in this module.)"
        }
      ],
      "functions": [],
      "state_variables": [
        {
          "id": "SV-CONST-001",
          "name": "EMPTY_TRIE_ROOT",
          "type": "Root",
          "description": "The root hash of an empty Merkle Patricia Trie. Equal to keccak256(RLP(b'')), value 0x56e81f171bcc55a6ff8345e692c0f86e5b48e01b996cadc001622fb5e363b421."
        }
      ],
      "data_structures": [],
      "preconditions": [],
      "postconditions": []
    },
    {
      "id": "SG-TRIE-CRUD-OPERATIONS",
      "name": "Trie CRUD Operations (Set, Get, Copy)",
      "description": "Core read/write operations on the Trie data structure: trie_set for inserting/deleting entries, trie_get for lookups, and copy_trie for shallow copying.",
      "invariants": [
        {
          "id": "INV-CRUD-001",
          "text": "Setting a key to the trie's default value is equivalent to deleting the key. After trie_set(trie, key, trie.default), the key must not be present in trie._data."
        },
        {
          "id": "INV-CRUD-002",
          "text": "trie_get always returns trie.default for keys not present in the trie. It never raises a KeyError."
        },
        {
          "id": "INV-CRUD-003",
          "text": "copy_trie produces a shallow copy of _data; since only frozen (immutable) objects are stored, this is safe and the copy is independent of the original."
        }
      ],
      "functions": [
        {
          "id": "FN-CRUD-001",
          "name": "trie_set",
          "signature": "trie_set(trie: Trie[K, V], key: K, value: V) -> None",
          "description": "Stores an item in the Merkle Trie. Deletes the key if value equals trie.default (since the trie represents default values by omission). Otherwise sets trie._data[key] = value.",
          "parameters": [
            {"name": "trie", "type": "Trie[K, V]", "description": "The trie to store in."},
            {"name": "key", "type": "K (Bytes)", "description": "The key to set."},
            {"name": "value", "type": "V", "description": "The value to insert. If equal to trie.default, the key is deleted."}
          ],
          "return_type": "None",
          "side_effects": ["Mutates trie._data: inserts or deletes a key-value pair."]
        },
        {
          "id": "FN-CRUD-002",
          "name": "trie_get",
          "signature": "trie_get(trie: Trie[K, V], key: K) -> V",
          "description": "Gets an item from the Merkle Trie. Returns trie.default if the key is missing.",
          "parameters": [
            {"name": "trie", "type": "Trie[K, V]", "description": "The trie to lookup in."},
            {"name": "key", "type": "K (Bytes)", "description": "The key to lookup."}
          ],
          "return_type": "V",
          "side_effects": []
        },
        {
          "id": "FN-CRUD-003",
          "name": "copy_trie",
          "signature": "copy_trie(trie: Trie[K, V]) -> Trie[K, V]",
          "description": "Creates a shallow copy of the trie. Since only frozen (immutable) objects may be stored, contents are safely reused.",
          "parameters": [
            {"name": "trie", "type": "Trie[K, V]", "description": "The trie to copy."}
          ],
          "return_type": "Trie[K, V]",
          "side_effects": []
        }
      ],
      "state_variables": [],
      "data_structures": [],
      "preconditions": [
        {
          "id": "PRE-CRUD-001",
          "function": "trie_set",
          "text": "The trie parameter must be a valid Trie instance. The key must be of type K (bound to Bytes). The value must match the trie's value type V."
        }
      ],
      "postconditions": [
        {
          "id": "POST-CRUD-001",
          "function": "trie_set",
          "text": "If value == trie.default and key was in trie._data, then key is no longer in trie._data after the call."
        },
        {
          "id": "POST-CRUD-002",
          "function": "trie_set",
          "text": "If value != trie.default, then trie._data[key] == value after the call."
        },
        {
          "id": "POST-CRUD-003",
          "function": "trie_get",
          "text": "Returns trie._data[key] if key is present, otherwise returns trie.default. The trie is not modified."
        },
        {
          "id": "POST-CRUD-004",
          "function": "copy_trie",
          "text": "The returned Trie has the same secured, default, and _data contents but _data is a distinct dict object (mutations to the copy do not affect the original)."
        }
      ]
    },
    {
      "id": "SG-NIBBLE-ENCODING",
      "name": "Nibble Encoding and Compact Serialization",
      "description": "Handles conversion between byte sequences and nibble lists, as well as Hex-Prefix (HP) compact encoding used in the MPT specification. Nibbles are 4-bit values (0-15) that represent individual hex digits of keys.",
      "invariants": [
        {
          "id": "INV-NIB-001",
          "text": "bytes_to_nibble_list produces a Bytes of length 2*len(input), where each output byte is in range [0, 15]."
        },
        {
          "id": "INV-NIB-002",
          "text": "nibble_list_to_compact encodes the is_leaf flag and parity in the highest nibble: bit 1 = is_leaf, bit 0 = parity (odd length). The encoding is reversible."
        },
        {
          "id": "INV-NIB-003",
          "text": "For even-length nibble lists, a leading zero nibble is prepended (with flag in high nibble). For odd-length, the first nibble of the key is packed with the flag nibble."
        }
      ],
      "functions": [
        {
          "id": "FN-NIB-001",
          "name": "nibble_list_to_compact",
          "signature": "nibble_list_to_compact(x: Bytes, is_leaf: bool) -> Bytes",
          "description": "Compresses a nibble-list into a standard byte array with a Hex-Prefix flag. The flag nibble encodes both the is_leaf status and the parity of the nibble count. Even-length lists get a 0-nibble prefix; odd-length lists pack the first nibble with the flag.",
          "parameters": [
            {"name": "x", "type": "Bytes", "description": "Array of nibbles (each byte value <= 15)."},
            {"name": "is_leaf", "type": "bool", "description": "True for leaf nodes, False for extension nodes."}
          ],
          "return_type": "Bytes",
          "side_effects": [],
          "encoding_table": {
            "even_leaf": "high nibble = 0x20 (0010 0000)",
            "odd_leaf": "high nibble = 0x3X (0011 XXXX) where X = first nibble",
            "even_extension": "high nibble = 0x00 (0000 0000)",
            "odd_extension": "high nibble = 0x1X (0001 XXXX) where X = first nibble"
          }
        },
        {
          "id": "FN-NIB-002",
          "name": "bytes_to_nibble_list",
          "signature": "bytes_to_nibble_list(bytes_: Bytes) -> Bytes",
          "description": "Converts a Bytes sequence into a nibble-list format where each byte is split into two nibbles (high and low 4 bits).",
          "parameters": [
            {"name": "bytes_", "type": "Bytes", "description": "The byte sequence to convert."}
          ],
          "return_type": "Bytes",
          "side_effects": []
        },
        {
          "id": "FN-NIB-003",
          "name": "common_prefix_length",
          "signature": "common_prefix_length(a: Sequence, b: Sequence) -> int",
          "description": "Finds the length of the longest common prefix of two sequences. Returns the number of matching elements from the start.",
          "parameters": [
            {"name": "a", "type": "Sequence", "description": "First sequence."},
            {"name": "b", "type": "Sequence", "description": "Second sequence."}
          ],
          "return_type": "int",
          "side_effects": []
        }
      ],
      "state_variables": [],
      "data_structures": [],
      "preconditions": [
        {
          "id": "PRE-NIB-001",
          "function": "nibble_list_to_compact",
          "text": "All values in x must be in range [0, 15] (valid nibble values)."
        },
        {
          "id": "PRE-NIB-002",
          "function": "bytes_to_nibble_list",
          "text": "Input must be a valid Bytes sequence."
        }
      ],
      "postconditions": [
        {
          "id": "POST-NIB-001",
          "function": "nibble_list_to_compact",
          "text": "The output is a valid Hex-Prefix encoded byte array. The first byte encodes the flag nibble. The encoding preserves all information needed to reconstruct the original nibble list and is_leaf flag."
        },
        {
          "id": "POST-NIB-002",
          "function": "bytes_to_nibble_list",
          "text": "Output has length exactly 2 * len(input). Each output byte is in [0, 15]."
        }
      ]
    },
    {
      "id": "SG-NODE-ENCODING",
      "name": "Node Encoding (RLP Serialization)",
      "description": "Handles RLP encoding of internal trie nodes (LeafNode, ExtensionNode, BranchNode) and external node types (Account, Transaction, Receipt, etc.). Internal nodes are encoded to their RLP form and hashed with keccak256 if the encoding is >= 32 bytes.",
      "invariants": [
        {
          "id": "INV-ENC-001",
          "text": "None nodes are encoded as b'' (empty bytes)."
        },
        {
          "id": "INV-ENC-002",
          "text": "If the RLP encoding of a node is less than 32 bytes, the raw RLP structure (unencoded) is returned instead of its hash. This is the 'inline node' optimization."
        },
        {
          "id": "INV-ENC-003",
          "text": "If the RLP encoding of a node is >= 32 bytes, the keccak256 hash of the encoding is returned."
        },
        {
          "id": "INV-ENC-004",
          "text": "LeafNode is encoded as (nibble_list_to_compact(rest_of_key, True), value) — is_leaf flag is always True."
        },
        {
          "id": "INV-ENC-005",
          "text": "ExtensionNode is encoded as (nibble_list_to_compact(key_segment, False), subnode) — is_leaf flag is always False."
        },
        {
          "id": "INV-ENC-006",
          "text": "BranchNode is encoded as a 17-element list: the 16 subnodes followed by the value."
        }
      ],
      "functions": [
        {
          "id": "FN-ENC-001",
          "name": "encode_internal_node",
          "signature": "encode_internal_node(node: Optional[InternalNode]) -> Extended",
          "description": "Encodes a Merkle Trie internal node into its RLP form. If the RLP serialization is < 32 bytes, returns the unencoded structure directly (inline); otherwise returns keccak256 of the serialized bytes. None is encoded as b''.",
          "parameters": [
            {"name": "node", "type": "Optional[InternalNode]", "description": "The internal node to encode. None represents absence."}
          ],
          "return_type": "Extended",
          "side_effects": [],
          "error_conditions": [
            "Raises AssertionError if node is not None, LeafNode, ExtensionNode, or BranchNode."
          ]
        },
        {
          "id": "FN-ENC-002",
          "name": "encode_node",
          "signature": "encode_node(node: Node, storage_root: Optional[Bytes] = None) -> Bytes",
          "description": "Encodes a Node (external value) for storage in the Merkle Trie. Dispatches based on node type: Account uses encode_account with storage_root, Transaction/Receipt/Withdrawal/U256 use rlp.encode, Bytes is returned as-is, and other types delegate to previous_trie.encode_node.",
          "parameters": [
            {"name": "node", "type": "Node", "description": "The value node to encode."},
            {"name": "storage_root", "type": "Optional[Bytes]", "description": "The storage root for Account nodes. Required when node is Account."}
          ],
          "return_type": "Bytes",
          "side_effects": [],
          "error_conditions": [
            "Asserts storage_root is not None when node is an Account."
          ]
        }
      ],
      "state_variables": [],
      "data_structures": [],
      "preconditions": [
        {
          "id": "PRE-ENC-001",
          "function": "encode_internal_node",
          "text": "Node must be None, LeafNode, ExtensionNode, or BranchNode."
        },
        {
          "id": "PRE-ENC-002",
          "function": "encode_node",
          "text": "If node is an Account, storage_root must not be None."
        }
      ],
      "postconditions": [
        {
          "id": "POST-ENC-001",
          "function": "encode_internal_node",
          "text": "Returns either an inline RLP structure (if serialized form < 32 bytes) or a 32-byte keccak256 hash."
        },
        {
          "id": "POST-ENC-002",
          "function": "encode_node",
          "text": "Returns the RLP-encoded bytes representation of the node suitable for insertion into the trie."
        }
      ]
    },
    {
      "id": "SG-ROOT-COMPUTATION",
      "name": "Trie Root Computation",
      "description": "Computes the Merkle Patricia Trie root hash. This is the top-level entry point that prepares the trie data, recursively patricializes it into an internal node tree, and computes the final root hash.",
      "invariants": [
        {
          "id": "INV-ROOT-001",
          "text": "An empty trie always produces EMPTY_TRIE_ROOT (0x56e81f171bcc55a6ff8345e692c0f86e5b48e01b996cadc001622fb5e363b421)."
        },
        {
          "id": "INV-ROOT-002",
          "text": "For secured tries, all keys are keccak256-hashed before trie construction during _prepare_trie."
        },
        {
          "id": "INV-ROOT-003",
          "text": "The root hash is deterministic: the same set of key-value pairs always produces the same root regardless of insertion order."
        },
        {
          "id": "INV-ROOT-004",
          "text": "If the RLP encoding of the root node is < 32 bytes, it is hashed with keccak256 anyway (unlike internal nodes which can be inlined). This ensures root is always a 32-byte hash."
        },
        {
          "id": "INV-ROOT-005",
          "text": "During _prepare_trie, any value that encodes to b'' triggers an AssertionError — empty-encoded values must not exist in the prepared mapping."
        }
      ],
      "functions": [
        {
          "id": "FN-ROOT-001",
          "name": "root",
          "signature": "root(trie: Trie[K, V], get_storage_root: Optional[Callable[[Address], Root]] = None) -> Root",
          "description": "Computes the root hash of a modified Merkle Patricia Trie (MPT). First prepares the trie data (hashing keys if secured, encoding values), then recursively patricializes the data into internal nodes, and finally encodes the root node. If the root encoding is < 32 bytes, it is keccak256-hashed; otherwise the hash is used directly.",
          "parameters": [
            {"name": "trie", "type": "Trie[K, V]", "description": "The trie to compute the root of."},
            {"name": "get_storage_root", "type": "Optional[Callable[[Address], Root]]", "description": "Function to get the storage root of an account. Required when trie contains Account values."}
          ],
          "return_type": "Root (32 bytes)",
          "side_effects": []
        },
        {
          "id": "FN-ROOT-002",
          "name": "_prepare_trie",
          "signature": "_prepare_trie(trie: Trie[K, V], get_storage_root: Optional[Callable[[Address], Root]] = None) -> Mapping[Bytes, Bytes]",
          "description": "Prepares the trie for root calculation. Iterates all key-value pairs, encodes each value via encode_node, hashes keys with keccak256 (if secured), and converts keys to nibble-list format. Returns a mapping from nibble-encoded keys to encoded values.",
          "parameters": [
            {"name": "trie", "type": "Trie[K, V]", "description": "The trie to prepare."},
            {"name": "get_storage_root", "type": "Optional[Callable[[Address], Root]]", "description": "Function to get storage root for Account encoding."}
